const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api/v1';

async function request(path, options = {}) {
  const response = await fetch(`${API_URL}${path}`, {
    ...options,
    credentials: 'include',
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.message || 'Something went wrong');
  return body;
}

export function registerUser(data) {
  return request('/users/register', { method: 'POST', body: JSON.stringify(data) });
}

export function loginUser(data) {
  return request('/users/login', { method: 'POST', body: JSON.stringify(data) });
}

export function logoutUser() {
  return request('/users/logout', { method: 'POST' });
}

export function getTasks() {
  return request('/tasks');
}

export function createTask(title) {
  return request('/tasks', { method: 'POST', body: JSON.stringify({ title }) });
}

export function updateTask(taskId, updates) {
  return request(`/tasks/${taskId}`, { method: 'PATCH', body: JSON.stringify(updates) });
}

export function deleteTask(taskId) {
  return request(`/tasks/${taskId}`, { method: 'DELETE' });
}
